# Regenerates revision3_checks.json for the V18 package (author's pipeline, 2026-10-21).
import hashlib, json, math, os, sys, time
import numpy as np
from scipy.special import ellipk, ellipe
PKG = sys.argv[1]; OUTF = sys.argv[2]
sys.path.insert(0, os.path.join(PKG, "code"))
import fields as F, tophat_finite_source as T1
from energy_integrator import Integrator
J = json.load(open(os.path.join(PKG, "csv", "fixed_case_numbers.json"), encoding="utf-8"))
out = {"_header": {
  "file": "revision3_checks.json",
  "generated": "2026-10-21",
  "generated_by": "Regenerated by the author's pipeline (David Szabolcsi) on 2026-10-21 by running make_revision3_checks.py on the V18 package. "
                  "This is NOT the reviewer's original revision3_checks.json; the reviewer's script check_revision3.py is not available.",
  "package": "V18 (GitHub V18; Zenodo V20 = 10.5281/zenodo.23540741, plus the two revision3 review text edits)",
  "nature": "Computational checks only; no raw clock data."}}
# 1) SHA-256 integrity
ents = []
for line in open(os.path.join(PKG, "SHA256SUMS.txt"), encoding="utf-8"):
    h, p = line.strip().split(None, 1)
    act = hashlib.sha256(open(os.path.join(PKG, p), "rb").read()).hexdigest()
    ents.append({"path": p, "expected": h, "actual": act, "ok": act == h})
out["sha256_integrity"] = {"n_entries": len(ents), "n_ok": sum(e["ok"] for e in ents), "entries": ents}
# geometry as in final_fixed.py
N, ell, Dm, NC, Rax, hz, I0 = 2000, 0.400, 0.2917, 8, 0.45, 0.200 - 0.300, 0.014
a = Dm / 2
cs = np.array([[Rax * math.cos(2 * math.pi * i / NC), Rax * math.sin(2 * math.pi * i / NC), hz] for i in range(NC)])
pref = np.array([1.60, 0.0, 0.0]); MU0 = 4e-7 * math.pi
# 2) independent B: sum of N discrete circular loops per coil (own elliptic-integral loop formula)
def loop(rho, z, R, I):
    m = 4 * R * rho / ((R + rho) ** 2 + z ** 2); K, E = ellipk(m), ellipe(m)
    d = np.sqrt((R + rho) ** 2 + z ** 2); q = (R - rho) ** 2 + z ** 2; C = MU0 * I / (2 * math.pi)
    Bz = C / d * (K + (R * R - rho ** 2 - z ** 2) / q * E)
    Br = np.where(rho > 0, C * z / np.where(rho > 0, rho, 1) / d * (-K + (R * R + rho ** 2 + z ** 2) / q * E), 0.0)
    return Br, Bz
def B_loops(P, I):
    zt = (np.arange(N) + 0.5) / N * ell - ell / 2; B = np.zeros(3)
    for c in cs:
        d = P - c; rho = math.hypot(d[0], d[1]); Br, Bz = loop(rho, d[2] - zt, a, I)
        Br, Bz = Br.sum(), Bz.sum()
        if rho > 0: B[0] += Br * d[0] / rho; B[1] += Br * d[1] / rho
        B[2] += Bz
    return B
def B_pkg(P, I): return F.coils_B(np.array([P], float), cs, a, ell, N * I, [1] * NC)[0]
bres = {}
for name, P in (("main_clock", np.zeros(3)), ("reference_clock", pref)):
    bl, bp = np.linalg.norm(B_loops(P, I0)), np.linalg.norm(B_pkg(P, I0))
    bres[name] = {"B_independent_loops_T": float(bl), "B_package_solenoid_T": float(bp), "rel_diff": float((bp - bl) / bl)}
bres["main_clock"]["B_json_Bpa_x_I0_T"] = J["Bpa"] * I0; bres["reference_clock"]["B_json_Bref_x_I0_T"] = J["Bref_pa"] * I0
bres["method"] = "Independent: 8 coils x 2000 discrete circular loops (midpoint z positions), loop field with scipy ellipk/ellipe. Package: fields.coils_B (Derby & Olbert current sheet). I = 14 mA, D = 291.7 mm (measured)."
out["B_field_check"] = bres
# 3) targeted main-peak rerun
t0 = time.time(); I = Integrator(cs, a, ell, N, pref, nhi=24000)
Lp = 0.6309573444801932; dW = I.dW(Lp)
kg = -T1.G * Lp ** 2 / T1.C2 * (dW / T1.C2 / T1.vball(Lp))
out["main_peak_rerun"] = {"L_m": Lp, "dW_J_per_A2": dW, "k_g_per_A2_rerun": kg, "k_g_per_A2_json": J["TAL_diff"]["k_g"],
  "rel_diff": (kg - J["TAL_diff"]["k_g"]) / J["TAL_diff"]["k_g"], "signal_14mA_rerun": kg * I0 ** 2,
  "signal_14mA_json": J["rows"][0]["Sg"], "settings": "nhi=24000 (base)", "runtime_s": round(time.time() - t0, 1)}
# 4) outer-integral checks: package base (nlo=6000, nt=32) vs refined far-field settings (nlo=12000, nt=64) vs json
Ib = Integrator(cs, a, ell, N, pref, nlo=12000, nt=64)
oc = []
for L in (2.6, 3.0, 10.0, 100.0):
    base = I.dW_B(L); fine = Ib.dW_B(L)
    row = {"L_m": L, "dW_B_base_nlo6000_nt32": base, "dW_B_refined_nlo12000_nt64": fine, "rel_diff_refined_vs_base": (fine - base) / base}
    key = {2.6: "2.6", 10.0: "10.0", 100.0: "100.0"}.get(L)
    if key: row["dW_json_conv_base"] = J["conv"][key][0]; row["rel_diff_rerun_vs_json"] = (base - J["conv"][key][0]) / J["conv"][key][0]
    if L == 3.0: row["dW_A_panels_tail"] = I.dW_A(L); row["rel_diff_A_vs_B"] = (row["dW_A_panels_tail"] - base) / base
    oc.append(row)
out["outer_integral_checks"] = {"rows": oc, "note": "Far-field resolution variation: nlo and nt changed together (6000->12000, 32->64)."}
# 5) L = 0.95 m residual arithmetic
inn, outr = J["jump_LJ"]["NHI24000 (alap)"]; w0, w1 = J["W_total"]["NHI24000 (alap)"]
out["L095_residual"] = {"dW_inner_J_per_A2": inn, "dW_outer_J_per_A2": outr, "diff_J_per_A2": inn - outr,
  "diff_percent_of_inner": 100 * (inn - outr) / inn, "W_total_main": w0, "W_total_ref": w1, "W_total_diff": w0 - w1,
  "identity_check_abs": abs((inn - outr) - (w0 - w1)), "source": "csv/fixed_case_numbers.json (jump_LJ, W_total; NHI24000 base)"}
json.dump(out, open(OUTF, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
print(json.dumps({k: v for k, v in out.items() if k != "sha256_integrity"}, indent=1, ensure_ascii=False)); print("sha", out["sha256_integrity"]["n_ok"], "/", out["sha256_integrity"]["n_entries"])
